if (points.size() < 3) return 0;

std::vector<std::pair<std::size_t, std::size_t>> edges;
std::vector<std::size_t> indices(points.size());
for (std::size_t i = 0; i < points.size(); ++i) indices[i] = i;

auto circumradius = [&](std::size_t i, std::size_t j, std::size_t k) -> double {
    const Point2d& a = points[i];
    const Point2d& b = points[j];
    const Point2d& c = points[k];
    double ab = (a.x - b.x)*(a.x - b.x) + (a.y - b.y)*(a.y - b.y);
    double bc = (b.x - c.x)*(b.x - c.x) + (b.y - c.y)*(b.y - c.y);
    double ca = (c.x - a.x)*(c.x - a.x) + (c.y - a.y)*(c.y - a.y);
    double area = (b.x - a.x)*(c.y - a.y) - (b.y - a.y)*(c.x - a.x);
    if (area == 0.0) return std::numeric_limits<double>::infinity();
    return std::sqrt(ab * bc * ca) / (2.0 * std::abs(area));
};

for (std::size_t i = 0; i < points.size(); ++i) {
    for (std::size_t j = i + 1; j < points.size(); ++j) {
        for (std::size_t k = j + 1; k < points.size(); ++k) {
            double r = circumradius(i, j, k);
            if (r <= alpha) {
                edges.emplace_back(i, j);
                edges.emplace_back(j, k);
                edges.emplace_back(k, i);
            }
        }
    }
}

std::sort(edges.begin(), edges.end());
edges.erase(std::unique(edges.begin(), edges.end()), edges.end());

std::vector<int> parent(points.size());
for (std::size_t i = 0; i < points.size(); ++i) parent[i] = static_cast<int>(i);

auto find = [&](int u) {
    while (parent[u] != u) {
        parent[u] = parent[parent[u]];
        u = parent[u];
    }
    return u;
};

auto unite = [&](int u, int v) {
    int pu = find(u);
    int pv = find(v);
    if (pu != pv) parent[pv] = pu;
};

for (const auto& e : edges) {
    unite(static_cast<int>(e.first), static_cast<int>(e.second));
}

std::unordered_set<int> components;
for (std::size_t i = 0; i < points.size(); ++i) {
    components.insert(find(static_cast<int>(i)));
}

return static_cast<int>(components.size());
